style.css:
@-moz-document domain("youtube.com") {
body, ytd-app {
        background-color: #1e1b18 !important;
        color: #e0d6c3 !important;
        font-family: "Georgia", "Times New Roman", serif !important;
    }

    ytd-watch-flexy, #content, #page-manager {
        background-color: #1e1b18 !important;
    }

    ytd-video-primary-info-renderer, ytd-comments, ytd-video-secondary-info-renderer {
        background-color: #2c2623 !important;
        color: #e0d6c3 !important;
    }

    ytd-thumbnail, ytd-rich-item-renderer, ytd-video-renderer, ytd-grid-video-renderer {
        background-color: #2c2623 !important;
        border: 1px solid #403c38 !important;
    }

    a, h1, h2, h3, h4, h5, h6 {
        color: #c1b49a !important;
    }

    yt-formatted-string, span, div {
        color: #d6cbb7 !important;
    }

    #search-input, ytd-searchbox {
        background-color: #2f2b28 !important;
        color: #e0d6c3 !important;
        border-radius: 4px !important;
    }

    ytd-masthead {
        background-color: #161410 !important;
        border-bottom: 1px solid #403c38;
    }

    paper-button, tp-yt-paper-button, button {
        background-color: #403c38 !important;
        color: #e0d6c3 !important;
    }

    ytd-guide-section-renderer, ytd-guide-entry-renderer {
        background-color: #1e1b18 !important;
        color: #d6cbb7 !important;
    }

    /* Remove bright thumbnails hover effect */
    ytd-thumbnail:hover {
        filter: brightness(0.9);
    }

    /* Scrollbar styling */
    ::-webkit-scrollbar {
        width: 10px;
    }

    ::-webkit-scrollbar-track {
        background: #1e1b18;
    }

    ::-webkit-scrollbar-thumb {
        background-color: #403c38;
        border-radius: 5px;
    }

    ::-webkit-scrollbar-thumb:hover {
        background-color: #5c5248;
    }
}
